    "src/screens/DailyMoodTracker.jsx": "import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addMoodEntry } from '../store/moodTrackingSlice';
import MoodTrackerCard from '../components/MoodTrackerCard';

const DailyMoodTracker = () => {
  const dispatch = useDispatch();
  const moods = useSelector((state) => state.moodTracking.moods);
  const [selectedMood, setSelectedMood] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleAddMood = () => {
    if (selectedMood && date) {
      dispatch(addMoodEntry({ date, value: selectedMood }));
      setSelectedMood('');
    }
  };

  const moodOptions = ['Happy', 'Neutral', 'Sad', 'Anxious', 'Relaxed', 'Stressed', 'Energetic', 'Tired'];

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-4xl font-bold text-indigo-700 mb-8">Daily Mood Tracker</h1>

      <div className="bg-white p-6 rounded-lg shadow-lg mb-8">
        <h2 className="text-2xl font-semibold mb-4">How are you feeling today?</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
          {moodOptions.map((mood) => (
            <button
              key={mood}
              onClick={() => setSelectedMood(mood)}
              className={`py-3 px-4 rounded-full text-lg font-medium transition-all duration-200\n                ${selectedMood === mood
                  ? 'bg-indigo-600 text-white shadow-md'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                }`}
            >
              {mood}
            </button>
          ))}
        </div>
        <div className="flex flex-col md:flex-row gap-4 items-center mb-4">
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="p-3 border border-gray-300 rounded-md w-full md:w-auto text-gray-700"
          />
          <button
            onClick={handleAddMood}
            disabled={!selectedMood || !date}
            className="flex-grow bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-6 rounded-md transition-colors duration-300 disabled:opacity-50"
          >
            Log Mood
          </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-2xl font-semibold text-indigo-700 mb-4">Your Recent Moods</h2>
        {moods.length === 0 ? (
          <p className="text-gray-600">No moods logged yet. Start tracking your feelings!</p>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {moods.slice().sort((a, b) => new Date(b.date) - new Date(a.date)).map((mood) => (
              <MoodTrackerCard key={mood.id} moodEntry={mood} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default DailyMoodTracker;",
