    "src/screens/CommunityForum.jsx": "import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addPost } from '../store/communityDiscussionsSlice';
import CommunityPost from '../components/CommunityPost';

const CommunityForum = () => {
  const dispatch = useDispatch();
  const posts = useSelector((state) => state.communityDiscussions.posts);
  const user = useSelector((state) => state.auth.user); // Assuming user is logged in
  const [newPostTitle, setNewPostTitle] = useState('');
  const [newPostContent, setNewPostContent] = useState('');

  const handleAddPost = (e) => {
    e.preventDefault();
    if (newPostTitle.trim() && newPostContent.trim() && user) {
      dispatch(addPost({
        userId: user.id,
        username: user.username,
        title: newPostTitle,
        content: newPostContent,
      }));
      setNewPostTitle('');
      setNewPostContent('');
    } else if (!user) {
      alert('You must be logged in to post.');
    }
  };

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-4xl font-bold text-indigo-700 mb-8">Community Forum</h1>

      <div className="bg-white p-6 rounded-lg shadow-lg mb-8">
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">Share Your Thoughts</h2>
        <form onSubmit={handleAddPost} className="space-y-4">
          <div>
            <label htmlFor="postTitle" className="block text-sm font-medium text-gray-700">Title</label>
            <input
              type="text"
              id="postTitle"
              value={newPostTitle}
              onChange={(e) => setNewPostTitle(e.target.value)}
              className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-indigo-500 focus:border-indigo-500"
              placeholder="What's on your mind?"
              required
              disabled={!user}
            />
          </div>
          <div>
            <label htmlFor="postContent" className="block text-sm font-medium text-gray-700">Content</label>
            <textarea
              id="postContent"
              value={newPostContent}
              onChange={(e) => setNewPostContent(e.target.value)}
              rows="4"
              className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-indigo-500 focus:border-indigo-500"
              placeholder="Write your post here..."
              required
              disabled={!user}
            ></textarea>
          </div>
          <button
            type="submit"
            className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-2 px-4 rounded-md transition-colors duration-300 disabled:opacity-50"
            disabled={!user}
          >
            Create Post
          </button>
          {!user && <p className="text-red-500 text-sm mt-2">Log in to create a post.</p>}
        </form>
      </div>

      <div className="space-y-6">
        <h2 className="text-2xl font-semibold text-indigo-700">Recent Discussions</h2>
        {posts.length === 0 ? (
          <p className="text-gray-600">No discussions yet. Be the first to post!</p>
        ) : (
          posts.slice().sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp)).map((post) => (
            <CommunityPost key={post.id} post={post} />
          ))
        )}
      </div>
    </div>
  );
};

export default CommunityForum;",
