import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const journalEntriesSlice = createSlice({
  name: 'journalEntries',
  initialState: {
    entries: [], // [{ id: 'uuid', date: 'YYYY-MM-DD', title: 'My Day', content: '...' }]
  },
  reducers: {
    addEntry: (state, action) => {
      const { title, content, date } = action.payload;
      state.entries.push({ id: uuidv4(), date: date || new Date().toISOString().split('T')[0], title, content });
    },
    updateEntry: (state, action) => {
      const { id, title, content } = action.payload;
      const existingEntry = state.entries.find(entry => entry.id === id);
      if (existingEntry) {
        existingEntry.title = title;
        existingEntry.content = content;
      }
    },
    deleteEntry: (state, action) => {
      state.entries = state.entries.filter(entry => entry.id !== action.payload);
    },
  },
});

export const { addEntry, updateEntry, deleteEntry } = journalEntriesSlice.actions;
export default journalEntriesSlice.reducer;

