import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const meditationSessionSlice = createSlice({
  name: 'meditationSession',
  initialState: {
    sessions: [], // [{ id: 'uuid', date: 'YYYY-MM-DD', duration: 10, type: 'guided' }]
    currentSession: null,
  },
  reducers: {
    startSession: (state, action) => {
      state.currentSession = { id: uuidv4(), startTime: Date.now(), ...action.payload };
    },
    endSession: (state) => {
      if (state.currentSession) {
        const duration = Math.round((Date.now() - state.currentSession.startTime) / 60000); // duration in minutes
        state.sessions.push({ ...state.currentSession, endTime: Date.now(), duration });
        state.currentSession = null;
      }
    },
  },
});

export const { startSession, endSession } = meditationSessionSlice.actions;
export default meditationSessionSlice.reducer;

