import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const communityDiscussionsSlice = createSlice({
  name: 'communityDiscussions',
  initialState: {
    posts: [], // [{ id: 'uuid', userId: 'user123', username: 'TestUser', timestamp: 'ISOString', title: 'Hello', content: '...', comments: [] }]
  },
  reducers: {
    addPost: (state, action) => {
      const { userId, username, title, content } = action.payload;
      state.posts.push({
        id: uuidv4(),
        userId,
        username,
        timestamp: new Date().toISOString(),
        title,
        content,
        comments: [],
      });
    },
    addComment: (state, action) => {
      const { postId, userId, username, content } = action.payload;
      const post = state.posts.find(p => p.id === postId);
      if (post) {
        post.comments.push({
          id: uuidv4(),
          userId,
          username,
          timestamp: new Date().toISOString(),
          content,
        });
      }
    },
  },
});

export const { addPost, addComment } = communityDiscussionsSlice.actions;
export default communityDiscussionsSlice.reducer;

