  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleAddMood = () => {
    if (selectedMood && date) {
      dispatch(addMoodEntry({ date, value: selectedMood }));
      setSelectedMood('');
    }
  };

  const moodOptions = ['Happy', 'Neutral', 'Sad', 'Anxious', 'Relaxed', 'Stressed', 'Energetic', 'Tired'];

  return (
