frontend.src/components/MeditationTimer.jsx:
import React, { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { startSession, endSession } from '../store/meditationSessionSlice';

const MeditationTimer = () => {
  const dispatch = useDispatch();
  const currentSession = useSelector((state) => state.meditationSession.currentSession);
  const [isActive, setIsActive] = useState(false);
  const [seconds, setSeconds] = useState(0);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (isActive) {
      intervalRef.current = setInterval(() => {
        setSeconds((prevSeconds) => prevSeconds + 1);
      }, 1000);
    } else if (!isActive && seconds !== 0) {
      clearInterval(intervalRef.current);
    }
    return () => clearInterval(intervalRef.current);
  }, [isActive, seconds]);

  const toggleTimer = () => {
    if (isActive) {
      // Stop session
      dispatch(endSession());
      setIsActive(false);
      setSeconds(0);
    } else {
      // Start session
      dispatch(startSession({ type: 'guided' })); // Default type for now
      setIsActive(true);
    }
  };

  const formatTime = (totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const remainingSeconds = totalSeconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg text-center">
      <h2 className="text-3xl font-bold mb-4">Meditation Timer</h2>
      <div className="text-6xl font-mono mb-6 text-indigo-700">
        {formatTime(seconds)}
      </div>
      <button
        onClick={toggleTimer}
        className={`px-8 py-3 rounded-full text-white font-semibold text-lg transition-all duration-300 ${
          isActive ? 'bg-red-500 hover:bg-red-600' : 'bg-green-500 hover:bg-green-600'
        }`}
      >
        {isActive ? 'Stop Session' : 'Start Session'}
      </button>
      {currentSession && isActive && (
        <p className="mt-4 text-gray-600">Session started at: {new Date(currentSession.startTime).toLocaleTimeString()}</p>
      )}
    </div>
  );
};

export default MeditationTimer;

